  gap: 12px;
  align-items: center;
  background: var(--card);
  color: var(--foreground);
  padding: 14px 18px;
  border: 1px solid var(--border);
  border-radius: 12px;
  box-shadow: 0 12px 40px #00000020;
  z-index: 100;
}
.command-results {
