  border-bottom: 1px solid var(--border);
}
.command-results a:hover {
  background: var(--muted);
}
.field-error {
  color: var(--destructive);
  font-size: 0.8125rem;
}
.loading-state {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 60px;
}
.loading-spinner {
  animation: spin 1s linear infinite;
}
.empty-state {
  text-align: center;
  padding: 50px 20px;
  color: var(--muted-foreground);
}
.empty-state svg {
  margin: 0 auto 16px;
}
.empty-state h3 {
  margin-bottom: 8px;
  color: var(--foreground);
}
.muted {
  color: var(--muted-foreground);
}
.eyebrow {
  display: block;
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  margin-bottom: 16px;
  color: var(--muted-foreground);
}
.spread {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
}
.filter-chips {
